using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "HornetDustEffect", menuName = "Data/Battle/Effects/Austra/HornetDust Effect")]
public class HornetDustEffect : Effect
{
	[Header("HornetDustEffect")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		GameObject gameObject = currentCorruptedAnimals.IsCorruptedAnimalWithHornetDust();
		if ((bool)gameObject && gameObject != effectOwner)
		{
			gameObject.GetComponent<UnitEffects>().RemoveEffect(this);
		}
	}

	public void CheckIfAnotherEnemyIsHornetDustAndRemoveIt(GameObject unitPurified)
	{
		GameObject gameObject = currentCorruptedAnimals.IsCorruptedAnimalWithHornetDust();
		if ((bool)gameObject && gameObject != unitPurified)
		{
			gameObject.GetComponent<UnitEffects>().RemoveEffect(this);
		}
	}

	public override void OnRemoveEffectEndOfBattle(int effectAmount, GameObject effectOwner)
	{
		RemoveEffect(effectAmount, effectOwner);
	}
}
